7	public class TrackRenderer
8	{
9	    private readonly GraphicsDevice _device;
10	    private readonly BasicEffect _effect;
11	
12	    public TrackRenderer(GraphicsDevice device)
13	    {
14	        _device = device;
15	        _effect = new BasicEffect(device)
16	        {
17	            VertexColorEnabled = true,
18	            TextureEnabled = true,
19	        };
20	    }
21	
22	    public void Draw(CameraService camera, TextureService textures, GameplayService? gameplay)
23	    {
24	        _effect.View = camera.View;
25	        _effect.Projection = camera.Projection;
26	        _effect.World = Matrix.Identity;
27	
28	        _device.DepthStencilState = DepthStencilState.Default;
29	        _device.BlendState = BlendState.AlphaBlend;
30	        _device.RasterizerState = RasterizerState.CullNone;
31	        _device.SamplerStates[0] = SamplerState.LinearClamp;
32	
33	        DrawTrackSurface(textures);
34	        DrawLaneDividers(textures);
35	        DrawCriticalLine(textures);
36	        if (gameplay != null)
37	            DrawBeatlines(textures, gameplay);
38	    }
39	
40	    private void DrawTrackSurface(TextureService textures)
41	    {
42	        float left = ArcFormula.LaneToWorldX(4);
43	        float right = ArcFormula.LaneToWorldX(1);
44	        float far = -Values.TrackLengthForward;
45	        float near = Values.TrackLengthBackward;
46	
47	        _effect.Texture = textures.Get("track");
48	        var color = new Color(180, 180, 200, 220);
49	
50	        var verts = new VertexPositionColorTexture[]
51	        {
52	            new(new Vector3(left, 0, far), color, new Vector2(0, 0)),
53	            new(new Vector3(right, 0, far), color, new Vector2(1, 0)),
54	            new(new Vector3(right, 0, near), color, new Vector2(1, 1)),
55	            new(new Vector3(left, 0, near), color, new Vector2(0, 1)),
56	        };
57	        var indices = new short[] { 0, 1, 2, 0, 2, 3 };
58	
59	        foreach (var pass in _effect.CurrentTechnique.Passes)
60	        {
61	            pass.Apply();
62	            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
63	        }
64	    }
65	
66	    private void DrawLaneDividers(TextureService textures)
67	    {
68	        _effect.Texture = textures.Has("trackDivider") ? textures.Get("trackDivider") : textures.White;
69	        Color lineColor = new Color(150, 150, 180, 120);
70	        float width = 0.06f;
71	        float far = -Values.TrackLengthForward;
72	        float near = Values.TrackLengthBackward;
73	
74	        var allVerts = new List<VertexPositionColorTexture>();
75	        var allIndices = new List<short>();
76	
77	        for (int lane = 1; lane <= 4; lane++)
78	        {
79	            float x = ArcFormula.LaneToWorldX(lane);
80	            short offset = (short)allVerts.Count;
81	            allVerts.Add(new(new Vector3(x - width, 0.01f, far), lineColor, new Vector2(0, 0)));
82	            allVerts.Add(new(new Vector3(x + width, 0.01f, far), lineColor, new Vector2(1, 0)));
83	            allVerts.Add(new(new Vector3(x + width, 0.01f, near), lineColor, new Vector2(1, 1)));
84	            allVerts.Add(new(new Vector3(x - width, 0.01f, near), lineColor, new Vector2(0, 1)));
85	            allIndices.AddRange(new short[] { offset, (short)(offset + 1), (short)(offset + 2), offset, (short)(offset + 2), (short)(offset + 3) });
86	        }
87	
88	        foreach (var pass in _effect.CurrentTechnique.Passes)
89	        {
90	            pass.Apply();
91	            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList,
92	                allVerts.ToArray(), 0, allVerts.Count, allIndices.ToArray(), 0, allIndices.Count / 3);
93	        }
94	    }
95	
96	    private void DrawCriticalLine(TextureService textures)
97	    {
98	        _effect.Texture = textures.Get("criticalLine");
99	        float left = ArcFormula.LaneToWorldX(4) - 1f;
100	        float right = ArcFormula.LaneToWorldX(1) + 1f;
101	        float height = 0.3f;
102	        Color color = new Color(255, 255, 255, 230);
103	
104	        var verts = new VertexPositionColorTexture[]
105	        {
106	            new(new Vector3(left, 0.02f, -height), color, new Vector2(0, 0)),
