using Microsoft.Xna.Framework;
using BetterArc.Gameplay;

namespace BetterArc.Render;

public class CameraService
{
    public Matrix View { get; private set; } = Matrix.Identity;
    public Matrix Projection { get; private set; } = Matrix.Identity;
    public Vector3 Position { get; private set; }

    public void Update(float aspectRatio)
    {
        // Camera behind judgment line (Z=0), looking toward approaching notes (-Z)
        // Unity uses -CameraZ but their camera faces +Z via Y=180° rotation;
        // MonoGame needs +CameraZ with forward toward -Z to achieve the same view.
        Position = new Vector3(0, Values.CameraY, Values.CameraZ);

        float rotXRad = MathHelper.ToRadians(Values.CameraRotX);
        var forward = new Vector3(0, -MathF.Sin(rotXRad), -MathF.Cos(rotXRad));
        var target = Position + forward * 100f;

        View = Matrix.CreateLookAt(Position, target, Vector3.Up);
        Projection = Matrix.CreatePerspectiveFieldOfView(
            MathHelper.ToRadians(60f), aspectRatio, 0.1f, 300f);
    }
}

