1	using Microsoft.Xna.Framework;
2	using Microsoft.Xna.Framework.Graphics;
3	using BetterArc.Gameplay;
4	using BetterArc.Gameplay.Data;
5	
6	namespace BetterArc.Render;
7	
8	public class NoteRenderer
9	{
10	    private readonly GraphicsDevice _device;
11	    private readonly BasicEffect _effect;
12	
13	    private static readonly Color[] ArcColors =
14	    {
15	        new Color(0, 200, 255),
16	        new Color(255, 100, 200),
17	    };
18	    private static readonly Color TraceColor = new Color(180, 180, 180, 100);
19	    private static readonly Color ShadowColor = new Color(0, 0, 0, 120);
20	
21	    public NoteRenderer(GraphicsDevice device)
22	    {
23	        _device = device;
24	        _effect = new BasicEffect(device)
25	        {
26	            VertexColorEnabled = true,
27	            TextureEnabled = true,
28	        };
29	    }
30	
31	    public void Draw(CameraService camera, GameplayService gameplay, TextureService textures)
32	    {
33	        if (gameplay.Chart == null) return;
34	
35	        _effect.View = camera.View;
36	        _effect.Projection = camera.Projection;
37	        _effect.World = Matrix.Identity;
38	
39	        _device.DepthStencilState = DepthStencilState.Default;
40	        _device.BlendState = BlendState.AlphaBlend;
41	        _device.RasterizerState = RasterizerState.CullNone;
42	        _device.SamplerStates[0] = SamplerState.LinearClamp;
43	
44	        for (int tg = 0; tg < gameplay.Chart.TimingGroups.Count; tg++)
45	        {
46	            DrawArcShadows(gameplay, tg, textures);
47	            DrawHolds(gameplay, tg, textures);
48	            DrawTaps(gameplay, tg, textures);
49	            DrawArcs(gameplay, tg, textures);
50	            DrawHeightIndicators(gameplay, tg, textures);
51	        }
52	    }
53	
54	    private void DrawTaps(GameplayService gameplay, int tg, TextureService textures)
55	    {
56	        _effect.Texture = textures.Get("tap");
57	
58	        foreach (var tap in gameplay.GetVisibleTaps(tg))
59	        {
60	            float z = gameplay.GetNoteZ(tg, tap.Timing);
61	            float x = ArcFormula.LaneToWorldX(tap.Lane);
62	            float alpha = ArcFormula.CalculateFadeOutAlpha(z);
63	            float scale = ArcFormula.CalculateTapSizeScalar(z) * 0.25f;
64	            Color color = Color.White * alpha;
65	
66	            DrawTexturedQuad(new Vector3(x, 0.15f, z), scale, scale * 0.3f, color);
67	        }
68	    }
69	
70	    private void DrawHolds(GameplayService gameplay, int tg, TextureService textures)
71	    {
72	        _effect.Texture = textures.Get("hold");
73	
74	        foreach (var hold in gameplay.GetVisibleHolds(tg))
75	        {
76	            float zStart = gameplay.GetNoteZ(tg, hold.Timing);
77	            float zEnd = gameplay.GetNoteZ(tg, hold.EndTiming);
78	            float x = ArcFormula.LaneToWorldX(hold.Lane);
79	
80	            float clippedStart = Math.Clamp(zStart, -Values.TrackLengthForward, Values.TrackLengthBackward);
81	            float clippedEnd = Math.Clamp(zEnd, -Values.TrackLengthForward, Values.TrackLengthBackward);
82	
83	            float halfWidth = Values.LaneWidth * 0.4f;
84	            float uvLen = Math.Abs(clippedEnd - clippedStart) * Values.HoldLengthScalar;
85	            Color color = new Color(255, 255, 255, (int)(Values.MaxHoldAlpha * 255));
86	
87	            var verts = new VertexPositionColorTexture[]
88	            {
89	                new(new Vector3(x - halfWidth, 0.05f, clippedStart), color, new Vector2(0, 0)),
90	                new(new Vector3(x + halfWidth, 0.05f, clippedStart), color, new Vector2(1, 0)),
91	                new(new Vector3(x + halfWidth, 0.05f, clippedEnd), color, new Vector2(1, uvLen)),
92	                new(new Vector3(x - halfWidth, 0.05f, clippedEnd), color, new Vector2(0, uvLen)),
93	            };
94	            var indices = new short[] { 0, 1, 2, 0, 2, 3 };
95	
96	            _device.SamplerStates[0] = SamplerState.LinearWrap;
97	            foreach (var pass in _effect.CurrentTechnique.Passes)
98	            {
99	                pass.Apply();
100	                _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
101	            }
102	            _device.SamplerStates[0] = SamplerState.LinearClamp;
103	        }
104	    }
105	
106	    private void DrawArcs(GameplayService gameplay, int tg, TextureService textures)
107	    {
108	        _effect.Texture = textures.Get("arcBody");
109	
110	        foreach (var arc in gameplay.GetVisibleArcs(tg))
111	        {
112	            Color baseColor = arc.IsTrace ? TraceColor
113	                : ArcColors[Math.Clamp(arc.Color, 0, ArcColors.Length - 1)];
114	
115	            float offset = arc.IsTrace ? Values.TraceMeshOffset : Values.ArcMeshOffset;
116	            float maxAlpha = arc.IsTrace ? Values.TraceAlphaScalar : Values.MaxArcAlpha;
117	
118	            int segments = Math.Max(1, (arc.EndTiming - arc.Timing) / 50);
119	            segments = Math.Min(segments, 200);
120	
121	            var allVerts = new List<VertexPositionColorTexture>();
122	            var allIndices = new List<short>();
123	
124	            for (int i = 0; i < segments; i++)
125	            {
126	                float t0 = (float)i / segments;
127	                float t1 = (float)(i + 1) / segments;
128	
129	                int timing0 = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t0);
130	                int timing1 = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t1);
131	
132	                float z0 = gameplay.GetNoteZ(tg, timing0);
133	                float z1 = gameplay.GetNoteZ(tg, timing1);
134	
135	                if (!ArcFormula.WithinRenderRange(z0) && !ArcFormula.WithinRenderRange(z1)) continue;
136	
137	                float ax0 = ArcFormula.X(arc.XStart, arc.XEnd, t0, arc.LineType);
138	                float ay0 = ArcFormula.Y(arc.YStart, arc.YEnd, t0, arc.LineType);
139	                float ax1 = ArcFormula.X(arc.XStart, arc.XEnd, t1, arc.LineType);
140	                float ay1 = ArcFormula.Y(arc.YStart, arc.YEnd, t1, arc.LineType);
141	
142	                float wx0 = ArcFormula.ArcXToWorld(ax0);
143	                float wy0 = ArcFormula.ArcYToWorld(ay0);
144	                float wx1 = ArcFormula.ArcXToWorld(ax1);
145	                float wy1 = ArcFormula.ArcYToWorld(ay1);
146	
147	                float alpha0 = ArcFormula.CalculateFadeOutAlpha(z0) * maxAlpha;
148	                float alpha1 = ArcFormula.CalculateFadeOutAlpha(z1) * maxAlpha;
149	                Color c0 = baseColor * alpha0;
150	                Color c1 = baseColor * alpha1;
151	
152	                var start = new Vector3(wx0, wy0, z0);
153	                var end = new Vector3(wx1, wy1, z1);
154	
155	                BuildDiamondSegment(allVerts, allIndices, start, end, offset, c0, c1);
156	            }
157	
158	            if (allVerts.Count >= 3)
159	            {
160	                _device.SamplerStates[0] = SamplerState.LinearWrap;
161	                foreach (var pass in _effect.CurrentTechnique.Passes)
162	                {
163	                    pass.Apply();
164	                    _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList,
165	                        allVerts.ToArray(), 0, allVerts.Count,
166	                        allIndices.ToArray(), 0, allIndices.Count / 3);
167	                }
168	                _device.SamplerStates[0] = SamplerState.LinearClamp;
169	            }
170	        }
171	    }
172	
173	    private void DrawArcShadows(GameplayService gameplay, int tg, TextureService textures)
174	    {
175	        _effect.Texture = textures.Get("shadow");
176	
177	        foreach (var arc in gameplay.GetVisibleArcs(tg))
178	        {
179	            if (arc.IsTrace) continue;
180	
181	            int segments = Math.Max(1, (arc.EndTiming - arc.Timing) / 100);
182	            segments = Math.Min(segments, 100);
183	
184	            for (int i = 0; i <= segments; i++)
185	            {
186	                float t = (float)i / segments;
187	                int timing = arc.Timing + (int)((arc.EndTiming - arc.Timing) * t);
188	                float z = gameplay.GetNoteZ(tg, timing);
189	                if (!ArcFormula.WithinRenderRange(z)) continue;
190	
191	                float ax = ArcFormula.X(arc.XStart, arc.XEnd, t, arc.LineType);
192	                float wx = ArcFormula.ArcXToWorld(ax);
193	                float alpha = ArcFormula.CalculateFadeOutAlpha(z) * 0.5f;
194	
195	                DrawTexturedQuad(new Vector3(wx, 0.02f, z), 1.2f, 0.3f, ShadowColor * alpha);
196	            }
197	        }
198	    }
199	
200	    private void DrawHeightIndicators(GameplayService gameplay, int tg, TextureService textures)
201	    {
202	        _effect.Texture = textures.Get("heightIndicator");
203	
204	        foreach (var arc in gameplay.GetVisibleArcs(tg))
205	        {
206	            if (arc.IsTrace) continue;
207	
208	            float z = gameplay.GetNoteZ(tg, arc.Timing);
209	            if (!ArcFormula.WithinRenderRange(z)) continue;
210	
211	            float wx = ArcFormula.ArcXToWorld(arc.XStart);
212	            float wy = ArcFormula.ArcYToWorld(arc.YStart);
213	            float alpha = ArcFormula.CalculateFadeOutAlpha(z) * 0.7f;
214	            Color color = ArcColors[Math.Clamp(arc.Color, 0, ArcColors.Length - 1)] * alpha;
215	
216	            // Vertical line from ground to arc start
217	            var verts = new VertexPositionColorTexture[]
218	            {
219	                new(new Vector3(wx - 0.15f, 0.01f, z), color, new Vector2(0, 1)),
220	                new(new Vector3(wx + 0.15f, 0.01f, z), color, new Vector2(1, 1)),
221	                new(new Vector3(wx + 0.15f, wy, z), color, new Vector2(1, 0)),
222	                new(new Vector3(wx - 0.15f, wy, z), color, new Vector2(0, 0)),
223	            };
224	            var indices = new short[] { 0, 1, 2, 0, 2, 3 };
225	
226	            foreach (var pass in _effect.CurrentTechnique.Passes)
227	            {
228	                pass.Apply();
229	                _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
230	            }
231	        }
232	    }
233	
234	    private static void BuildDiamondSegment(
235	        List<VertexPositionColorTexture> verts, List<short> indices,
236	        Vector3 start, Vector3 end, float offset, Color c0, Color c1)
237	    {
238	        short baseIdx = (short)verts.Count;
239	
240	        // Diamond cross-section matching ArcMeshGenerator
241	        // Top center, right-bottom, left-bottom
242	        float halfOff = offset / 2f;
243	
244	        // v0: top center start, v1: top center end
245	        // v2: right-bottom end, v3: right-bottom start
246	        // v4: left-bottom end, v5: left-bottom start
247	        verts.Add(new(start + new Vector3(0, halfOff, 0), c0, new Vector2(0, 0)));
248	        verts.Add(new(end + new Vector3(0, halfOff, 0), c1, new Vector2(1, 0)));
249	        verts.Add(new(end + new Vector3(offset, -halfOff, 0), c1, new Vector2(1, 1)));
250	        verts.Add(new(start + new Vector3(offset, -halfOff, 0), c0, new Vector2(0, 1)));
251	        verts.Add(new(end + new Vector3(-offset, -halfOff, 0), c1, new Vector2(1, 1)));
252	        verts.Add(new(start + new Vector3(-offset, -halfOff, 0), c0, new Vector2(0, 1)));
253	
254	        // 4 triangles: right face (0,3,2)(0,2,1), left face (0,1,4)(0,4,5)
255	        indices.AddRange(new short[]
256	        {
257	            baseIdx, (short)(baseIdx + 3), (short)(baseIdx + 2),
258	            baseIdx, (short)(baseIdx + 2), (short)(baseIdx + 1),
259	            baseIdx, (short)(baseIdx + 1), (short)(baseIdx + 4),
260	            baseIdx, (short)(baseIdx + 4), (short)(baseIdx + 5),
261	        });
