1	using Microsoft.Xna.Framework;
2	using Microsoft.Xna.Framework.Graphics;
3	using Microsoft.Xna.Framework.Input;
4	using BetterArc.Render;
5	using BetterArc.Input;
6	using BetterArc.Judgment;
7	
8	namespace BetterArc;
9	
10	public class BetterArcGame : Game
11	{
12	    private GraphicsDeviceManager _graphics;
13	    private SpriteBatch? _spriteBatch;
14	    private CameraService? _camera;
15	    private TextureService? _textures;
16	    private TrackRenderer? _track;
17	    private NoteRenderer? _notes;
18	    private Gameplay.GameplayService? _gameplay;
19	    private InputService? _input;
20	    private ScoreService? _score;
21	    private bool _autoPlay = true;
22	    private KeyboardState _prevKb;
23	
24	    private readonly HashSet<int> _judgedTapTimings = new();
25	    private string _lastJudgment = "";
26	    private int _lastJudgmentTime;
27	
28	    public BetterArcGame()
29	    {
30	        _graphics = new GraphicsDeviceManager(this);
31	        _graphics.PreferredBackBufferWidth = 1280;
32	        _graphics.PreferredBackBufferHeight = 720;
33	        Window.Title = "BetterArc v2";
34	        IsMouseVisible = true;
35	    }
36	
37	    protected override void Initialize()
38	    {
39	        _camera = new CameraService();
40	        _textures = new TextureService();
41	        _textures.Initialize(GraphicsDevice);
42	        _track = new TrackRenderer(GraphicsDevice);
43	        _notes = new NoteRenderer(GraphicsDevice);
44	        _gameplay = new Gameplay.GameplayService();
45	        _input = new InputService();
46	        _score = new ScoreService();
47	
48	        string chartPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "assets", "charts", "sayonarahatsukoi_ftr.aff");
49	        if (File.Exists(chartPath))
50	        {
51	            _gameplay.LoadChart(File.ReadAllText(chartPath));
52	            int totalNotes = _gameplay.Chart!.TimingGroups.Sum(
53	                tg => tg.Taps.Count + tg.Holds.Count + tg.Arcs.Count(a => !a.IsTrace));
54	            _score.SetNoteCount(totalNotes);
55	        }
56	
57	        base.Initialize();
58	    }
59	
60	    protected override void LoadContent()
61	    {
62	        _spriteBatch = new SpriteBatch(GraphicsDevice);
63	    }
64	
65	    protected override void Update(GameTime gameTime)
66	    {
67	        var kb = Keyboard.GetState();
68	        _input!.Update();
69	
70	        // Toggle auto-play with A key
71	        if (kb.IsKeyDown(Keys.A) && _prevKb.IsKeyUp(Keys.A))
72	            _autoPlay = !_autoPlay;
73	
74	        // Timeline scrubbing
75	        int speed = kb.IsKeyDown(Keys.LeftShift) ? 100 : 20;
76	        if (kb.IsKeyDown(Keys.Right))
77	            _gameplay!.CurrentTiming += speed;
78	        if (kb.IsKeyDown(Keys.Left))
79	            _gameplay!.CurrentTiming = Math.Max(0, _gameplay.CurrentTiming - speed);
80	        if (kb.IsKeyDown(Keys.Space) && _prevKb.IsKeyUp(Keys.Space))
81	            _gameplay!.CurrentTiming = 0;
82	
83	        // Judgment processing
84	        if (_gameplay!.Chart != null)
85	            ProcessJudgments();
86	
87	        float aspect = GraphicsDevice.Viewport.AspectRatio;
88	        _camera!.Update(aspect);
89	        _prevKb = kb;
90	
91	        base.Update(gameTime);
92	    }
93	
94	    private void ProcessJudgments()
95	    {
96	        if (_gameplay?.Chart == null) return;
97	
98	        for (int tg = 0; tg < _gameplay.Chart.TimingGroups.Count; tg++)
99	        {
100	            foreach (var tap in _gameplay.Chart.TimingGroups[tg].Taps)
101	            {
102	                int key = tap.Timing * 1000 + tg;
103	                if (_judgedTapTimings.Contains(key)) continue;
104	
105	                int offset = _gameplay.CurrentTiming - tap.Timing;
106	
107	                if (offset > Gameplay.Values.MissJudgeWindow)
108	                {
109	                    _judgedTapTimings.Add(key);
110	                    var result = JudgmentResult.MissLate;
111	                    _score!.ProcessResult(result);
112	                    ShowJudgment(result, offset);
113	                    continue;
114	                }
115	
116	                if (_autoPlay && Math.Abs(offset) <= 5)
117	                {
118	                    _judgedTapTimings.Add(key);
119	                    _score!.ProcessResult(JudgmentResult.Max);
120	                    ShowJudgment(JudgmentResult.Max, 0);
121	                    continue;
122	                }
123	
124	                if (!_autoPlay && JudgmentService.IsWithinWindow(offset))
125	                {
126	                    int lane = (int)Math.Round(tap.Lane);
127	                    if (_input!.IsLaneJustPressed(lane))
128	                    {
129	                        _judgedTapTimings.Add(key);
130	                        var result = JudgmentService.Judge(offset);
131	                        _score!.ProcessResult(result);
132	                        ShowJudgment(result, offset);
133	                    }
134	                }
135	            }
136	        }
137	    }
138	
139	    private void ShowJudgment(JudgmentResult result, int offset)
140	    {
141	        string earlyLate = offset < 0 ? " EARLY" : offset > 0 ? " LATE" : "";
142	        _lastJudgment = result switch
143	        {
144	            JudgmentResult.Max => "PURE",
145	            JudgmentResult.PerfectEarly or JudgmentResult.PerfectLate => $"PURE{earlyLate}",
146	            JudgmentResult.GoodEarly or JudgmentResult.GoodLate => $"FAR{earlyLate}",
147	            _ => "LOST",
148	        };
149	        _lastJudgmentTime = _gameplay!.CurrentTiming;
150	    }
151	
152	    protected override void Draw(GameTime gameTime)
153	    {
154	        GraphicsDevice.Clear(Color.Black);
155	
156	        if (_camera != null && _track != null && _notes != null && _gameplay != null && _textures != null)
157	        {
158	            _track.Draw(_camera, _textures, _gameplay);
159	            _notes.Draw(_camera, _gameplay, _textures);
160	        }
161	
162	        DrawHUD();
163	        base.Draw(gameTime);
164	    }
165	
166	    private void DrawHUD()
167	    {
168	        if (_spriteBatch == null || _score == null || _gameplay == null) return;
169	
170	        _spriteBatch.Begin();
171	
172	        string mode = _autoPlay ? "[AUTO]" : "[D/F/J/K]";
173	        string hud = $"{mode}  Score: {_score.Score:N0}  Combo: {_score.CurrentCombo}  " +
174	                      $"Max:{_score.MaxCount} P:{_score.PerfectCount} G:{_score.GoodCount} M:{_score.MissCount}  " +
175	                      $"t={_gameplay.CurrentTiming}ms";
176	
177	        // Draw judgment text (fade out after 500ms)
178	        if (_gameplay.CurrentTiming - _lastJudgmentTime < 500 && _lastJudgment.Length > 0)
179	        {
180	            hud += $"  [{_lastJudgment}]";
181	        }
182	
183	        // Simple text rendering without SpriteFont - use Window title as HUD
184	        Window.Title = $"BetterArc v2 — {hud}";
185	
186	        _spriteBatch.End();
187	    }
188	
189	    public CameraService Camera => _camera!;
190	    public Gameplay.GameplayService GameplayService => _gameplay!;
191	}
