- [ ] **Step 1: Write the extraction script**

Create `tools/extract_frames.sh`:

```bash
#!/bin/bash
set -euo pipefail

# Extract frames from ArcCreate export video at fixed intervals.
# Video start = chart time -2000ms.
# Output filenames encode chart time: t-02000.png, t00000.png, t00500.png, ...

usage() {
    echo "Usage: $0 <video> <interval_ms> <output_dir>"
    echo ""
    echo "  video:       ArcCreate exported video (1280x720)"
    echo "  interval_ms: extraction interval in milliseconds (e.g. 500)"
    echo "  output_dir:  directory to write PNGs"
    exit 1
}

[[ $# -lt 3 ]] && usage

VIDEO="$1"
INTERVAL_MS="$2"
OUTPUT_DIR="$3"

VIDEO_START_MS=-2000

if ! command -v ffprobe &>/dev/null || ! command -v ffmpeg &>/dev/null; then
    echo "Error: ffmpeg and ffprobe must be installed"
    exit 1
fi

if [[ ! -f "$VIDEO" ]]; then
    echo "Error: video file not found: $VIDEO"
    exit 1
fi

mkdir -p "$OUTPUT_DIR"

DURATION_SEC=$(ffprobe -v quiet -show_entries format=duration -of csv=p=0 "$VIDEO")
DURATION_MS=$(printf '%.0f' "$(echo "$DURATION_SEC * 1000" | bc)")

echo "Video duration: ${DURATION_MS}ms"
echo "Interval: ${INTERVAL_MS}ms"
echo "Output: $OUTPUT_DIR"

FRAME_COUNT=0
CURRENT_MS=0

while (( CURRENT_MS < DURATION_MS )); do
    CHART_TIME_MS=$(( VIDEO_START_MS + CURRENT_MS ))

    # Format chart time: 5 digits with sign
    if (( CHART_TIME_MS < 0 )); then
        ABS_TIME=$(( -CHART_TIME_MS ))
        FILENAME=$(printf "t-%05d.png" "$ABS_TIME")
    else
        FILENAME=$(printf "t%05d.png" "$CHART_TIME_MS")
    fi

    SEEK_SEC=$(echo "scale=3; $CURRENT_MS / 1000" | bc)

    ffmpeg -y -ss "$SEEK_SEC" -i "$VIDEO" -frames:v 1 -q:v 1 \
        "${OUTPUT_DIR}/${FILENAME}" -loglevel quiet

    FRAME_COUNT=$((FRAME_COUNT + 1))
    CURRENT_MS=$((CURRENT_MS + INTERVAL_MS))
done

echo "Extracted $FRAME_COUNT frames to $OUTPUT_DIR"
```

