```csharp
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;

namespace BetterArc.Tests.Visual;

public static class ImageComparer
{
    private const int WindowSize = 8;
    private const float C1 = 6.5025f;   // (0.01 * 255)^2
    private const float C2 = 58.5225f;  // (0.03 * 255)^2

    public static float ComputeSsim(string referencePath, string actualPath)
    {
        using var refImg = Image.Load<Rgba32>(referencePath);
        using var actImg = Image.Load<Rgba32>(actualPath);

        if (refImg.Width != actImg.Width || refImg.Height != actImg.Height)
            throw new ArgumentException(
                $"Image dimensions mismatch: reference {refImg.Width}x{refImg.Height} vs actual {actImg.Width}x{actImg.Height}");

        return ComputeSsimFromImages(refImg, actImg);
    }

    private static float ComputeSsimFromImages(Image<Rgba32> refImg, Image<Rgba32> actImg)
    {
        int w = refImg.Width;
        int h = refImg.Height;
        int windowsX = w / WindowSize;
        int windowsY = h / WindowSize;

        if (windowsX == 0 || windowsY == 0)
            return 1.0f;

        float totalSsim = 0;
        int windowCount = 0;

        for (int wy = 0; wy < windowsY; wy++)
        {
            for (int wx = 0; wx < windowsX; wx++)
            {
                int startX = wx * WindowSize;
                int startY = wy * WindowSize;
                totalSsim += ComputeWindowSsim(refImg, actImg, startX, startY);
                windowCount++;
            }
        }

        return totalSsim / windowCount;
    }

    private static float ComputeWindowSsim(
        Image<Rgba32> refImg, Image<Rgba32> actImg, int startX, int startY)
    {
        float sumRef = 0, sumAct = 0;
        float sumRefSq = 0, sumActSq = 0, sumRefAct = 0;
        int count = WindowSize * WindowSize;

        for (int dy = 0; dy < WindowSize; dy++)
        {
            for (int dx = 0; dx < WindowSize; dx++)
            {
                int x = startX + dx;
                int y = startY + dy;

                float r = PixelToLuma(refImg[x, y]);
                float a = PixelToLuma(actImg[x, y]);

                sumRef += r;
                sumAct += a;
                sumRefSq += r * r;
                sumActSq += a * a;
                sumRefAct += r * a;
            }
        }

        float muRef = sumRef / count;
        float muAct = sumAct / count;
        float sigmaRefSq = (sumRefSq / count) - (muRef * muRef);
        float sigmaActSq = (sumActSq / count) - (muAct * muAct);
        float sigmaRefAct = (sumRefAct / count) - (muRef * muAct);

        float numerator = (2 * muRef * muAct + C1) * (2 * sigmaRefAct + C2);
        float denominator = (muRef * muRef + muAct * muAct + C1) * (sigmaRefSq + sigmaActSq + C2);

        return numerator / denominator;
    }

    private static float PixelToLuma(Rgba32 p)
    {
        return 0.299f * p.R + 0.587f * p.G + 0.114f * p.B;
    }
}
