- [ ] **Step 1: Create VisualTestBase**

Create `BetterArc.Tests/Visual/VisualTestBase.cs`:

```csharp
using System.Text;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using BetterArc.Gameplay;
using BetterArc.Render;

namespace BetterArc.Tests.Visual;

public abstract class VisualTestBase : IDisposable
{
    protected abstract string ChartName { get; }
    protected abstract string ChartPath { get; }
    protected abstract float SsimThreshold { get; }

    protected int Width => 1280;
    protected int Height => 720;

    private HeadlessGame? _game;

    protected void RunVisualComparison()
    {
        string refDir = FindReferenceDir();
        if (refDir == null || !Directory.Exists(refDir))
        {
            Skip.If(true, $"No reference frames at TestData/L2/{ChartName}/");
            return;
        }

        var timePoints = ScanReferenceFrames(refDir);
        if (timePoints.Count == 0)
        {
            Skip.If(true, $"No reference frames found in {refDir}");
            return;
        }

        _game = new HeadlessGame(Width, Height);
        _game.RunOneFrame();

        var device = _game.GraphicsDevice;
        var camera = new CameraService();
        var textures = new TextureService();
        textures.Initialize(device);
        var track = new TrackRenderer(device);
        var notes = new NoteRenderer(device);
        var gameplay = new GameplayService();

        string chartFullPath = FindChartFile();
        gameplay.LoadChart(File.ReadAllText(chartFullPath));

        string outputDir = GetOutputDir();
        Directory.CreateDirectory(outputDir);

        var results = new List<FrameResult>();

        foreach (var (timeMs, refPath) in timePoints)
        {
            gameplay.CurrentTiming = timeMs;

            string actualPath = Path.Combine(outputDir, $"actual_t{FormatTime(timeMs)}.png");
            ScreenshotService.CaptureToFile(device, camera, textures, track, notes, gameplay,
                Width, Height, actualPath);

            string diffPath = Path.Combine(outputDir, $"diff_t{FormatTime(timeMs)}.png");
            float ssim = ImageComparer.GenerateDiff(refPath, actualPath, diffPath);

            results.Add(new FrameResult(timeMs, ssim, diffPath));
        }

        string reportPath = Path.Combine(outputDir, "report.txt");
        WriteReport(reportPath, results);

        var failed = results.Where(r => r.Ssim < SsimThreshold).ToList();
        if (failed.Count > 0)
        {
            var worst = failed.OrderBy(r => r.Ssim).First();
            Assert.Fail(
                $"L2 visual comparison failed: {failed.Count}/{results.Count} frames below threshold ({SsimThreshold:F2}).\n" +
                $"Worst: t{FormatTime(worst.TimeMs)} SSIM={worst.Ssim:F4}\n" +
                $"Report: {reportPath}");
        }
    }

    private string? FindReferenceDir()
    {
        string[] candidates =
        {
            Path.Combine(AppContext.BaseDirectory, "TestData", "L2", ChartName),
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "TestData", "L2", ChartName),
        };
        foreach (var c in candidates)
        {
            string resolved = Path.GetFullPath(c);
            if (Directory.Exists(resolved)) return resolved;
        }
        return null;
    }

    private string FindChartFile()
    {
        string[] candidates =
        {
            Path.Combine(AppContext.BaseDirectory, ChartPath),
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ChartPath),
        };
        foreach (var c in candidates)
        {
            string resolved = Path.GetFullPath(c);
            if (File.Exists(resolved)) return resolved;
        }
        throw new FileNotFoundException($"Chart file not found: {ChartPath}");
    }

    private static List<(int timeMs, string path)> ScanReferenceFrames(string dir)
    {
        var results = new List<(int, string)>();

        foreach (var file in Directory.GetFiles(dir, "t*.png"))
        {
            string name = Path.GetFileNameWithoutExtension(file);
            if (TryParseTime(name, out int timeMs))
                results.Add((timeMs, file));
        }

        results.Sort((a, b) => a.Item1.CompareTo(b.Item1));
        return results;
    }

    private static bool TryParseTime(string name, out int timeMs)
    {
        // Format: t-02000 or t00500
        timeMs = 0;
        if (name.Length < 2 || name[0] != 't') return false;

        string numPart = name.Substring(1);
        if (int.TryParse(numPart, out timeMs)) return true;
        return false;
    }

    private static string FormatTime(int timeMs)
    {
        if (timeMs < 0)
            return $"-{(-timeMs):D5}";
        return $"{timeMs:D5}";
    }

    private string GetOutputDir()
    {
        string baseDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "TestResults", "L2", ChartName);
        return Path.GetFullPath(baseDir);
    }

    private void WriteReport(string path, List<FrameResult> results)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Chart: {ChartName}");
        sb.AppendLine($"Threshold: {SsimThreshold:F2}");

        int passed = results.Count(r => r.Ssim >= SsimThreshold);
        int failed = results.Count - passed;
        sb.AppendLine($"Frames: {results.Count} total, {passed} passed, {failed} failed");
        sb.AppendLine();

        var failedFrames = results.Where(r => r.Ssim < SsimThreshold).OrderBy(r => r.Ssim).ToList();
        if (failedFrames.Count > 0)
        {
            sb.AppendLine("FAILED FRAMES:");
            foreach (var f in failedFrames)
                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}  diff: {Path.GetFileName(f.DiffPath)}");
            sb.AppendLine();
        }

        var worstPassed = results.Where(r => r.Ssim >= SsimThreshold)
            .OrderBy(r => r.Ssim).Take(5).ToList();
        if (worstPassed.Count > 0)
        {
            sb.AppendLine("PASSED FRAMES (worst 5):");
            foreach (var f in worstPassed)
                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}");
        }

        File.WriteAllText(path, sb.ToString());
    }

    public void Dispose()
    {
        _game?.Dispose();
    }

    private record FrameResult(int TimeMs, float Ssim, string DiffPath);
}

public class HeadlessGame : Game
{
    private readonly GraphicsDeviceManager _graphics;
    private readonly int _width;
    private readonly int _height;

    public HeadlessGame(int width, int height)
    {
        _width = width;
        _height = height;
        _graphics = new GraphicsDeviceManager(this)
        {
            PreferredBackBufferWidth = width,
            PreferredBackBufferHeight = height,
            GraphicsProfile = GraphicsProfile.HiDef,
        };
    }

    public void RunOneFrame()
    {
        RunOneFrame();
    }
}
```

**Important note on HeadlessGame:** MonoGame's `Game.Run()` starts the game loop and blocks. We need a way to initialize the `GraphicsDevice` without entering the loop. The approach depends on the MonoGame platform:

- On **DesktopGL (OpenGL)**: `Game` creates an SDL window. We can call the protected `DoInitialize()` method via reflection, or simply call `Run()` in a background thread and signal when `Initialize()` completes.
- A simpler approach: override `Initialize()`, `Update()`, and `Draw()`, then call `Run()` but immediately call `Exit()` after initialization.

Replace the `HeadlessGame` class with this working approach:

```csharp
public class HeadlessGame : Game
{
    private readonly GraphicsDeviceManager _graphics;
    private bool _initialized;

    public HeadlessGame(int width, int height)
    {
        _graphics = new GraphicsDeviceManager(this)
        {
            PreferredBackBufferWidth = width,
            PreferredBackBufferHeight = height,
            GraphicsProfile = GraphicsProfile.HiDef,
        };
    }

    protected override void Initialize()
    {
        base.Initialize();
        _initialized = true;
    }

    protected override void Update(GameTime gameTime)
    {
        if (_initialized)
            SuppressDraw();
    }

    public void RunOneFrame()
    {
        // Use MonoGame's internal tick mechanism.
        // On DesktopGL, calling RunOneFrame() drives the game loop for one frame.
        base.RunOneFrame();
    }

    public new GraphicsDevice GraphicsDevice => base.GraphicsDevice;
}
```

**If `RunOneFrame()` is not accessible** (protected in some MonoGame versions), use this fallback:

```csharp
public class HeadlessGame : Game
{
    private readonly GraphicsDeviceManager _graphics;
    private readonly ManualResetEventSlim _ready = new();
    private Thread? _gameThread;

    public HeadlessGame(int width, int height)
    {
        _graphics = new GraphicsDeviceManager(this)
        {
            PreferredBackBufferWidth = width,
            PreferredBackBufferHeight = height,
            GraphicsProfile = GraphicsProfile.HiDef,
        };
    }

    protected override void Initialize()
    {
        base.Initialize();
        _ready.Set();
    }

    protected override void BeginRun()
    {
        base.BeginRun();
    }

    public void Start()
    {
        _gameThread = new Thread(() => Run()) { IsBackground = true };
        _gameThread.Start();
        _ready.Wait(TimeSpan.FromSeconds(10));
        if (!_ready.IsSet)
            throw new TimeoutException("HeadlessGame failed to initialize within 10 seconds");
    }

    public new GraphicsDevice GraphicsDevice => base.GraphicsDevice;
}
```

**The implementer should try the `RunOneFrame()` approach first**, falling back to the threaded approach only if needed. MonoGame 3.8 DesktopGL exposes `RunOneFrame()` as a public method on `Game`.

