using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;

namespace BetterArc.Tests.Visual;

public class ImageComparerTests : IDisposable
{
    private readonly string _tempDir;

    public ImageComparerTests()
    {
        _tempDir = Path.Combine(Path.GetTempPath(), $"betterarc_test_{Guid.NewGuid():N}");
        Directory.CreateDirectory(_tempDir);
    }

    public void Dispose()
    {
        if (Directory.Exists(_tempDir))
            Directory.Delete(_tempDir, true);
    }

    [Fact]
    public void ComputeSsim_IdenticalImages_Returns1()
    {
        string path1 = Path.Combine(_tempDir, "a.png");
        string path2 = Path.Combine(_tempDir, "b.png");

        using (var img = new Image<Rgba32>(64, 64, new Rgba32(100, 150, 200, 255)))
        {
            img.Save(path1);
            img.Save(path2);
        }

        float ssim = ImageComparer.ComputeSsim(path1, path2);
        Assert.Equal(1.0f, ssim, precision: 3);
    }

    [Fact]
    public void ComputeSsim_CompletelyDifferentImages_ReturnsLow()
    {
        string path1 = Path.Combine(_tempDir, "black.png");
        string path2 = Path.Combine(_tempDir, "white.png");

        using (var img = new Image<Rgba32>(64, 64, new Rgba32(0, 0, 0, 255)))
            img.Save(path1);
        using (var img = new Image<Rgba32>(64, 64, new Rgba32(255, 255, 255, 255)))
            img.Save(path2);

        float ssim = ImageComparer.ComputeSsim(path1, path2);
        Assert.True(ssim < 0.1f, $"SSIM should be very low for opposite images, got {ssim}");
    }

    [Fact]
    public void ComputeSsim_SimilarImages_ReturnsMedium()
    {
        string path1 = Path.Combine(_tempDir, "a.png");
        string path2 = Path.Combine(_tempDir, "b.png");

        using (var img = new Image<Rgba32>(64, 64, new Rgba32(100, 150, 200, 255)))
            img.Save(path1);
        using (var img = new Image<Rgba32>(64, 64, new Rgba32(110, 160, 210, 255)))
            img.Save(path2);

        float ssim = ImageComparer.ComputeSsim(path1, path2);
        Assert.True(ssim > 0.9f, $"SSIM should be high for similar images, got {ssim}");
        Assert.True(ssim < 1.0f, $"SSIM should not be exactly 1.0 for different images, got {ssim}");
    }
}

