    public void GenerateDiff_CreatesDiffImage_ReturnsSsim()
    {
        string path1 = Path.Combine(_tempDir, "a.png");
        string path2 = Path.Combine(_tempDir, "b.png");
        string diffPath = Path.Combine(_tempDir, "diff.png");

        using (var img = new Image<Rgba32>(64, 64, new Rgba32(100, 100, 100, 255)))
            img.Save(path1);
        using (var img = new Image<Rgba32>(64, 64, new Rgba32(200, 100, 100, 255)))
            img.Save(path2);

        float ssim = ImageComparer.GenerateDiff(path1, path2, diffPath);

        Assert.True(ssim > 0 && ssim < 1.0f, $"SSIM should be between 0 and 1, got {ssim}");
        Assert.True(File.Exists(diffPath), "Diff image should be created");

        using var diffImg = Image.Load<Rgba32>(diffPath);
        Assert.Equal(64, diffImg.Width);
        Assert.Equal(64, diffImg.Height);

        var center = diffImg[32, 32];
        Assert.True(center.R > 0 || center.G > 0, "Diff should show non-zero difference");
    }

    [Fact]
